{"cards": [{"node_code": "N_29409a9ee6531afb", "definition": "研究铁路运输业务（客货运输、装卸、中转等）的经济规律、业务流程优化及业务量与效益关系的理论分支。", "boundary": "本节点聚焦于“运输业务”层面的经济分析与理论，区别于纯技术操作或宏观管理体制。边界在于区分“业务经济”与“工程技术”：涉及列车运行图编制、信号控制等纯技术归入工程节点；涉及业务量预测、业务成本分摊、客货流经济分析归入本节点。若涉及具体国家业务政策，侧重理论模型归本节点，侧重政策事实归国别节点。", "includes": ["铁路客货运输业务的经济分析与优化理论", "装卸、中转、仓储等辅助业务的成本与效率研究", "运输业务量预测及业务结构对经济效益的影响分析"], "excludes": ["列车运行图编制、信号控制等纯工程技术内容", "特定国家具体的运输业务政策文件或历史数据"], "sibling_distinctions": [{"other_code": "N_a3cd5e4ac1cce538", "rule": "区分依据为“业务过程”与“价格机制”：侧重运输作业流程、业务量与成本关系的归入本节点；侧重运价制定、票价结构、价格弹性等定价理论的归入成本运价节点。"}, {"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“业务运营”与“组织管理”：侧重具体运输业务环节的经济效率归入本节点；侧重企业组织架构、部门职能、人力资源管理等归入企业组织节点。"}], "cross_boundary_rule": "若内容涉及“高铁商务座定价”，侧重价格机制归入成本运价节点；若涉及“高铁商务座服务流程与收益管理”，侧重业务运营归入本节点。"}, {"node_code": "N_40586dc8dba9e177", "definition": "研究列车乘务人员（列车员、乘务长等）的劳动组织、岗位职责、服务标准及人力资源管理的理论分支。", "boundary": "本节点聚焦于“列车员”这一特定岗位的经济与管理属性，而非其具体操作技能或纯工程技术。边界在于区分“人员管理”与“技术操作”：涉及列车员服务礼仪、劳动定额、绩效考核、岗位设置归入本节点；涉及列车员使用的设备技术归入相应工程节点。若涉及特定国家列车员制度，侧重通用管理理论归本节点，侧重国别制度归国别节点。", "includes": ["列车乘务人员的劳动组织与岗位职责理论", "列车员服务标准、绩效考核及人力资源配置方法", "列车员培训体系及职业发展路径的经济分析"], "excludes": ["列车员使用的具体设备技术（如广播系统、车门控制）", "特定国家列车员的具体历史沿革或政策文件"], "sibling_distinctions": [{"other_code": "N_07aba58e8d817f26", "rule": "区分依据为“特定岗位”与“整体组织”：侧重列车员这一特定岗位的管理与服务归入本节点；侧重铁路企业整体组织架构、部门协调归入企业组织节点。"}, {"other_code": "N_29409a9ee6531afb", "rule": "区分依据为“人员”与“业务”：侧重乘务人员的管理与服务归入本节点；侧重客货运输业务本身的经济流程归入运输业务节点。"}], "cross_boundary_rule": "若内容涉及“列车员服务对旅客满意度的影响”，侧重服务管理与人员行为归入本节点；若涉及“旅客满意度对票价弹性的影响”，侧重价格机制归入成本运价节点。"}, {"node_code": "N_cb3df5a2ba3980fa", "definition": "研究轨道交通（含铁路）基础设施与移动设备的资产估值、投融资、证券化及经营效益的理论分支。", "boundary": "本节点聚焦于“资产管理”与“经营”的经济属性，区别于纯工程技术或宏观政策。边界在于区分“资产经济”与“工程技术”：涉及线路、车辆的设计制造归入工程节点；涉及资产折旧、估值、融资模式、资产证券化归入本节点。若涉及特定国家资产改革，侧重理论模型归本节点，侧重政策事实归国别节点。", "includes": ["轨道交通基础设施与车辆的资产估值与折旧理论", "轨道交通投融资模式、资产证券化及资本运作方法", "轨道交通资产经营效益分析与风险管理理论"], "excludes": ["轨道交通线路、车辆的设计、制造等纯工程技术内容", "特定国家具体的资产改革政策文件或历史数据"], "sibling_distinctions": [{"other_code": "N_